use coloyond_etf_math::{quote_exact_in, MathError};

#[test]
fn near_u64_tiny_inputs_keep_the_quote_within_one_unit_of_the_exact_floor() {
    // Exact floors independently generated by reference_weighted_integer.py's
    // arbitrary-precision invariant binary search.
    let balance_in = u64::MAX - 1_000;
    let cases = [(1, 99), (100, 9_899), (1_000, 98_999)];
    for (amount_in, exact_floor) in cases {
        let quote = quote_exact_in(&[balance_in, u64::MAX], &[9_900, 100], 0, 1, amount_in, 0)
            .unwrap_or_else(|error| panic!("positive exact output rejected: {error:?}"));

        assert!(
            quote.amount_out <= exact_floor,
            "quote overpays invariant floor"
        );
        assert!(
            exact_floor - quote.amount_out <= 1,
            "quote loses more than one unit: input={amount_in}, exact={exact_floor}, actual={}",
            quote.amount_out
        );
    }
}

#[test]
fn one_unit_output_dust_fails_closed_without_overpaying() {
    // Exact invariant check: (99 + 1) * (100 - 1) == 99 * 100.
    // The conservative Q96 upper bound may round this one-unit output to zero.
    assert_eq!(
        quote_exact_in(&[99, 100], &[5_000, 5_000], 0, 1, 1, 0),
        Err(MathError::NoOutput)
    );
}

#[test]
fn all_weight_steps_match_exact_tiny_input_boundaries_without_overpaying() {
    let mut tested = 0;
    for line in include_str!("weighted_tiny_u64_boundary_vectors.csv")
        .lines()
        .skip(1)
    {
        let values: Vec<u64> = line
            .split(',')
            .map(|field| field.parse().expect("valid integer vector"))
            .collect();
        let [balance_in, balance_out, weight_in, weight_out, amount_in, exact_floor] =
            <[u64; 6]>::try_from(values).expect("six vector columns");
        let quote = quote_exact_in(
            &[balance_in, balance_out],
            &[weight_in as u16, weight_out as u16],
            0,
            1,
            amount_in,
            0,
        );

        match quote {
            Ok(quote) => {
                assert!(quote.amount_out <= exact_floor, "quote overpays: {line}");
                assert!(
                    exact_floor - quote.amount_out <= 1,
                    "shortfall exceeds one base unit: {line}"
                );
            }
            Err(MathError::NoOutput) if exact_floor <= 1 => {}
            Err(error) => panic!("unexpected quote failure ({error:?}): {line}"),
        }
        tested += 1;
    }
    assert_eq!(
        tested, 297,
        "regenerate the exact-invariant boundary corpus"
    );
}
